<script setup>
import {ref,computed,onMounted,onUnmounted} from 'vue'
import {useArcade} from '../stores/arcade'
import PartnerImage from '../components/PartnerImage.vue'
import PixelDecor from '../components/PixelDecor.vue'
import DetectiveScene from '../components/detective/DetectiveScene.vue'
const s=useArcade()
function scrollGames(){document.getElementById('games')?.scrollIntoView({behavior:'smooth'})}
const games=[{url:'sql-detective',title:'SQL로 찾는 결정적 증거',name:'SQL 미스터리 탐정단',text:'단서 수집, 추격, 최종 범인 검거까지!',tag:'SQL · 5 LEVEL',color:'dungeon',reward:'최대 200P',isNew:true},{url:'python-dungeon',title:'코드로 여는 다섯 개의 문',name:'Python 코딩 던전 탈출',text:'탐험하고, 코드를 고치고, 던전을 탈출하세요.',tag:'Python · 5 LEVEL',color:'dungeon',reward:'최대 200P'},{url:'cards',icon:'🍓',title:'기억을 뒤집어 봐!',name:'카드 뒤집기',text:'포켓몬 카드의 같은 짝을 찾아요.',tag:'기억력',color:'pink',art:'🂠 ✦ 🂠',reward:'클리어 보상 3~50 코인'},{url:'quiz',icon:'💡',title:'오늘의 똑똑한 한 판',name:'퀴즈 타임',text:'7과목 700문제, 매번 새로운 도전!',tag:'상식',color:'yellow',art:'? 💡 ?',reward:'최초 정답 보상'},{url:'pet',icon:'🐻',title:'우리, 매일 만나!',name:'마이 리틀 펫',text:'먹이고 놀아주며 함께 자라요.',tag:'성장',color:'green',art:'🌼 🐻 🌱',reward:'코인 사용'},{url:'hidden',icon:'🔎',title:'꼭꼭 숨어라!',name:'숨은그림 찾기',text:'사진 속 이모지 10개! 10단계에 도전해요.',tag:'관찰력',color:'yellow',art:'🔎 🍀 ⭐',reward:'라운드 클리어 +3 포인트'}]
const gameStart=ref(0),gameCount=ref(4),gameHost=ref(null),visibleGames=computed(()=>games.slice(gameStart.value,gameStart.value+gameCount.value));let gameObserver
function turnGames(n){gameStart.value=Math.max(0,Math.min(games.length-gameCount.value,gameStart.value+n))}
onMounted(()=>{gameObserver=new ResizeObserver(entries=>{const width=entries[0].contentRect.width;gameCount.value=width<650?1:width<1000?2:width<1400?3:4;gameStart.value=Math.min(gameStart.value,Math.max(0,games.length-gameCount.value))});gameObserver.observe(gameHost.value)});onUnmounted(()=>gameObserver?.disconnect())
</script>
<template><div class="welcome-strip"><template v-if="s.user"><span class="welcome-decor"><PixelDecor kind="clover"/><b>{{s.user.nickname}}</b>님, 오늘도 한 단계 성장해요!</span><RouterLink to="/account">내 프로필 →</RouterLink></template><template v-else><span>🪙 로그인하고 학습 진도와 포인트를 확인해 보세요!</span><RouterLink to="/account">로그인 / 회원가입 →</RouterLink></template></div><section class="hero"><div><p class="eyebrow">YOUR EVERYDAY PLAYGROUND</p><h1>잠깐의 여유,<br>한 주머니의 즐거움<span>✦</span></h1><p>가볍게 한 판, 차곡차곡 모으는 행복.<br>오늘은 어떤 게임으로 쉬어갈까요?</p><button type="button" class="button" @click="scrollGames">게임 고르기 ↘</button></div><div class="hero-art"><PixelDecor kind="clover" class="hero-clover"/><span class="orbit o2">🪙</span><PartnerImage size="hero"/><span class="hero-label">LET'S PLAY A LITTLE!</span><PixelDecor kind="hearts" class="hero-hearts"/></div></section><div class="section-title" id="games"><div><p class="eyebrow">PICK YOUR HAPPY MOMENT</p><h2>오늘의 플레이리스트 <span>{{games.length}} GAMES</span></h2></div><span class="save-badge">{{s.user?"● 자동 저장 중":"로그인 후 코인 적립"}}</span></div><div class="game-carousel" ref="gameHost"><button class="game-carousel-arrow" aria-label="이전 게임" :disabled="gameStart===0" @click="turnGames(-1)">〈</button><div class="game-carousel-viewport"><section class="game-grid" :style="{'--cards-per-page':gameCount}"><RouterLink v-for="g in visibleGames" :key="g.url" :to="'/'+g.url" class="game-card"><div :class="['card-art',g.color]"><span v-if="g.isNew" class="new-game-badge">NEW!</span><DetectiveScene v-if="g.url==='sql-detective'" class="detective-thumbnail" :level="5" phase="title"/><img v-else-if="g.url==='python-dungeon'" class="dungeon-card-art" src="/images/dungeon/title.svg" alt="픽셀 코딩 던전"/><PartnerImage v-else-if="g.url==='pet'" size="card"/><PixelDecor v-else-if="g.url==='quiz'" kind="box" class="quiz-box-art"/><span v-else class="art-emoji">{{g.art}}</span><span class="tag">{{g.tag}}</span></div><div class="card-body"><small>{{g.title}}</small><h2>{{g.name}} <span>↗</span></h2><p>{{g.text}}</p><div class="card-bottom"><span>🪙 {{g.reward}}{{g.url==='quiz'?' 코인':''}}</span><b>플레이 →</b></div></div></RouterLink></section></div><button class="game-carousel-arrow" aria-label="다음 게임" :disabled="gameStart>=games.length-gameCount" @click="turnGames(1)">〉</button></div><p class="game-carousel-status">{{gameStart+1}}–{{Math.min(gameStart+gameCount,games.length)}} / {{games.length}} GAMES</p><section class="bottom-grid"><div class="panel pet-summary"><PartnerImage size="small"/><div><p class="eyebrow">MY LITTLE FRIEND</p><h3>{{s.petName}}가 기다리고 있어요</h3><p v-if="s.user?.role!=='admin'">Lv.{{s.level}} · 함께 놀고 추억을 쌓아 보세요.</p></div><RouterLink to="/pet" class="button light">만나러 가기 →</RouterLink></div><div class="panel"><p class="eyebrow">RECENT MOMENTS</p><h3>최근 포인트 내역</h3><p v-if="!s.data.records.length">퀴즈에서 최초 정답을 맞히고 기록을 쌓아 보세요!</p><div v-for="r in s.data.records.slice(0,3)" :key="r.at" class="record"><span>{{r.game}}</span><b>{{r.coins>0?'+':''}}{{r.coins}} 🪙</b></div></div></section></template>

<style scoped>
.game-carousel{display:grid;grid-template-columns:34px minmax(0,1fr) 34px;gap:12px;align-items:center;width:100%;min-width:0}.game-carousel-viewport{min-width:0;overflow:hidden;padding:3px 4px 8px}.game-carousel .game-grid{display:grid!important;grid-template-columns:repeat(var(--cards-per-page),minmax(0,1fr))!important;gap:16px;margin:0!important;min-width:0}.game-carousel .game-card{min-width:0;width:100%;height:100%;overflow:hidden;box-sizing:border-box}.game-carousel .card-art{position:relative;overflow:hidden;min-width:0}.game-carousel .card-body{min-width:0}.game-carousel .card-body h2{font-size:18px;line-height:1.6;min-height:58px;overflow-wrap:anywhere}.game-carousel .card-body p{min-height:40px;line-height:1.7}.game-carousel-arrow{margin:0;padding:8px 0;width:34px;min-width:0;height:48px;font-size:23px;line-height:1;box-sizing:border-box}.game-carousel-status{text-align:center;font-size:10px;margin:5px 0 14px}.new-game-badge{position:absolute;top:12px;right:12px;z-index:3;padding:5px 9px;background:#e9c86f;color:#142d3b;border:2px solid #233d43;font-size:12px;font-weight:bold;line-height:1.2}.dungeon-card-art{display:block;width:100%;height:100%;object-fit:cover;image-rendering:pixelated}.game-carousel .card-art.dungeon{background:#19343d}.game-carousel .card-art.dungeon .tag{z-index:2;background:#203e36;color:#ffe9ad;border-color:#e5c777}.game-carousel .card-bottom{gap:8px;flex-wrap:wrap;font-size:11px}@media(max-width:650px){.game-carousel{grid-template-columns:26px minmax(0,1fr) 26px;gap:6px}.game-carousel .game-grid{gap:8px}.game-carousel-arrow{width:26px;height:42px;font-size:18px}.game-carousel .card-body h2{font-size:17px;min-height:54px}.new-game-badge{font-size:10px;right:8px;top:8px}}
</style>
<style scoped>.detective-thumbnail{position:absolute;inset:0;height:100%!important;border:0!important;width:100%;pointer-events:none}.detective-thumbnail :deep(.sql-monster){animation:none!important}.detective-thumbnail :deep(.scene-caption){font-size:8px;top:32px}.detective-thumbnail :deep(.scene-detective){bottom:6%}.detective-thumbnail :deep(.scene-witness){top:27%}.detective-thumbnail :deep(.sql-monster){height:66px;width:48px}.game-carousel .detective-thumbnail+.tag{z-index:4}</style>
